// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != c.owner());

        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool success) {
            // If the call doesn't revert, the owner must stay the same in the correct contract.
            assertTrue(c.owner() == c.owner());
        } catch {
            // If the call reverts, the owner must stay the same in the correct contract.
            assertTrue(c.owner() != newOwner);
        }
    }
}

