pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // The owner is msg.sender (this test contract).
        // Only the current owner can call setOwner, so we prank as the owner (this).
        vm.prank(address(this));
        bool ok = false;
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }
        // After a successful onlyOwner call, owner must equal newOwner.
        assertTrue(!ok || c.owner() == newOwner);
    }
}

