pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(c));
        vm.prank(address(this));
        c.setOwner(address(this));
        vm.prank(address(this));
        c.setOwner(newOwner);
        address stored = c.owner();
        assertTrue(stored.code.length == 0 && address(stored).balance == 0);
        (bool success, ) = payable(stored).call{value: 1}("");
        assertTrue(success);
    }
}

